#!/usr/bin/env bash
# hiddenforge, one-shot deploy. Generated by `hiddenforge setup`.
# Usage: ./deploy.sh [path/to/your-compose.yml]
set -euo pipefail
cd "$(dirname "$0")"

BASE="${1:-compose.yml}"
if ! command -v docker >/dev/null 2>&1; then
    echo "docker not installed. Install Docker Engine first." >&2
    exit 1
fi

echo "==> Preparing key directory ./tor-keys"
mkdir -p ./tor-keys
chmod 700 ./tor-keys 2>/dev/null || :

echo "==> Bringing the stack up"
docker compose -f "$BASE" -f compose.service.yml up -d

echo "==> Waiting for the .onion address(es) (up to 180s each)"
for svc in blog; do
    onion=""
    for _ in $(seq 1 180); do
        onion=$(docker compose -f "$BASE" -f compose.service.yml exec -T tor \
            cat /var/lib/tor/hidden_service/$svc/hostname 2>/dev/null || true)
        if [ -n "$onion" ]; then break; fi
        sleep 1
    done
    echo
    echo "================================================================="
    if [ -n "$onion" ]; then
        echo "$svc .onion: $onion"
        echo "Persisted to: ./tor-keys/$svc/hostname and ./tor-keys/$svc.onion"
    else
        echo "$svc: address not ready yet; check the container logs"
    fi
done
echo "BACK UP THE ENTIRE ./tor-keys DIRECTORY. It IS your address."
echo "================================================================="
